const rows = $input.all().map(i => i.json).filter(r => r.platform_post_id);
if (!rows.length) return [{ json: { none: true } }];
return [{ json: { ids: rows.map(r => r.platform_post_id).join(','), map: Object.fromEntries(rows.map(r => [r.platform_post_id, r])) } }];

const map = $('Build ID List').first().json.map; const out = [];
for (const v of ($input.first().json.items || [])) { const r = map[v.id]; if (!r) continue; const s = v.statistics || {}; const avail = []; const n = k => (s[k] !== undefined ? (avail.push(k.replace('Count', 's')), Number(s[k])) : null);
  const views = n('viewCount'), likes = n('likeCount'), comments = n('commentCount');
  out.push({ json: { publication_id: r.publication_id, channel_id: r.channel_id, raw: v, views, likes, comments, avail: '{' + avail.join(',') + '}' } }); }
return out.length ? out : [{ json: { none: true } }];

const b = $input.first().json.body || {};
if (!['youtube', 'instagram', 'facebook'].includes(b.platform)) throw new Error('VALIDATION: platform');
if (!/^[A-Z]{3}$/.test(b.currency || '')) throw new Error('VALIDATION: currency must be ISO-4217, e.g. USD');
const amt = Number(b.gross_amount); if (!isFinite(amt) || amt < 0) throw new Error('VALIDATION: gross_amount');
if (!['estimated', 'confirmed'].includes(b.confirmation)) throw new Error('VALIDATION: confirmation must be estimated|confirmed');
return [{ json: { platform: b.platform, channel_id: b.channel_id || null, content_id: b.content_id || null, period_start: b.period_start, period_end: b.period_end, gross_amount: amt,
  currency: b.currency, usd_amount: b.usd_amount ?? null, program: b.program || null, rpm: b.rpm ?? null, confirmation: b.confirmation, payout_status: b.payout_status || null } }];

// Maps a database/validation outcome to an HTTP status + structured JSON. No stack traces / internals are ever returned.
const clean = m => String(m || '').replace(/^"+|"+$/g, '').replace(/^(?:Error: )?(?:VALIDATION: )?/, '').replace(/ \[line \d+\]$/, '').slice(0, 300);
const e = $input.first().json; return [{ json: { status: 400, body: { ok: false, error: 'VALIDATION', message: clean(e.error?.message ?? e.error ?? e.message) } } }];

// Maps a database/validation outcome to an HTTP status + structured JSON. No stack traces / internals are ever returned.
const clean = m => String(m || '').replace(/^"+|"+$/g, '').replace(/^(?:Error: )?(?:VALIDATION: )?/, '').replace(/ \[line \d+\]$/, '').slice(0, 300);
const j = $input.first().json; const r = (j.result !== undefined && j.result !== null) ? j.result : j;
if (r && r.ok === false) {
  const code = String(r.error || 'CONFLICT'); const map = { not_found: 404, NOT_FOUND: 404, stale_version: 409, CONFLICT: 409, blocked_assessment_cannot_be_approved: 409, not_awaiting: 409, no_schedule: 404, not_editable: 409, conflict_min_gap: 409, in_the_past: 422, already_published: 409, no_active_assessment: 404 };
  const status = map[code] || 400; const kind = status === 404 ? 'NOT_FOUND' : status === 409 ? 'CONFLICT' : status === 422 ? 'UNPROCESSABLE' : 'VALIDATION';
  return [{ json: { status, body: { ok: false, error: kind, code, message: clean(r.message || code.replace(/_/g, ' ')), details: r } } }];
}
return [{ json: { status: 200, body: { ok: true, ...(typeof r === 'object' ? r : { result: r }) } } }];

// Maps a database/validation outcome to an HTTP status + structured JSON. No stack traces / internals are ever returned.
const clean = m => String(m || '').replace(/^"+|"+$/g, '').replace(/^(?:Error: )?(?:VALIDATION: )?/, '').replace(/ \[line \d+\]$/, '').slice(0, 300);
const e = $input.first().json; const raw = String(e.error?.message ?? e.error ?? e.message ?? '');
if (/VALIDATION:/.test(raw)) return [{ json: { status: 400, body: { ok: false, error: 'VALIDATION', message: clean(raw) } } }];
if (/invalid input syntax|violates (check|foreign|unique|not-null)|duplicate key/i.test(raw)) return [{ json: { status: 422, body: { ok: false, error: 'UNPROCESSABLE', message: 'request conflicts with stored data or has an invalid value' } } }];
return [{ json: { status: 500, body: { ok: false, error: 'INTERNAL', message: 'internal error; see error log' } } }];
